foreach($visible as $g){$d=(int)$g['dia'];$slotKey=$d.'-'.substr($g['hora_inicio'],0,5).'-'.substr($g['hora_fin'],0,5);if(!isset($slots[$d][$slotKey]))$slots[$d][$slotKey]=array('id'=>'slot-'.(int)$g['id_grupo'],'start'=>pool_calendar_minutes($g['hora_inicio']),'end'=>pool_calendar_minutes($g['hora_fin']),'groups'=>array());$slots[$d][$slotKey]['groups'][]=$g;$startMin=min($startMin,pool_calendar_minutes($g['hora_inicio']));$endMin=max($endMin,pool_calendar_minutes($g['hora_fin']));}
