<div class="calendar-corner">Hora</div><?php foreach($calendarDays as $d=>$name){ ?><div class="calendar-day-title <?php if($d==(int)date('N'))echo 'is-today'; ?>"><strong><?php echo $name; ?></strong><small><?php echo isset($slots[$d])?count($slots[$d]):0; ?> clases</small></div><?php } ?>
