 $daySlots=isset($slots[$d])?pool_calendar_layout(array_values($slots[$d])):array();if(!$daySlots)echo '<p class="calendar-empty">Sin clases</p>';
 foreach($daySlots as $slot){$titles=array();$names=array();$search=array();$usedTotal=0;$capacityTotal=0;foreach($slot['groups'] as $g){$k=$g['id_grupo'].'-'.$g['id_subgrupo'];$list=isset($rosters[$k])?$rosters[$k]:array();$usedTotal+=count($list);$capacityTotal+=(int)$g['capacidad'];$titles[]=$g['nombre_tipo_grupo']?:'Natación';if(isset($team[$k]))$names=array_merge($names,$team[$k]);$search[]=$k;foreach($list as $s)$search[]=trim($s['Nombre'].' '.$s['Apellido1'].' '.$s['Apellido2']);}$titles=array_unique($titles);$names=array_unique($names);$first=$slot['groups'][0];$time=substr($first['hora_inicio'],0,5).' – '.substr($first['hora_fin'],0,5);$allSearch=$name.' '.$time.' '.implode(' ',$titles).' '.implode(' ',$names).' '.implode(' ',$search); ?>
 <button type="button" class="calendar-event <?php echo $slot['start']<840?'morning':'afternoon'; ?>" data-open="<?php echo $slot['id']; ?>" data-search="<?php echo app_escape($allSearch); ?>" data-groups="<?php echo count($slot['groups']); ?>" style="top:<?php echo ($slot['start']-$startMin)*2.4+2; ?>px;height:<?php echo max(30,($slot['end']-$slot['start'])*2.4-4); ?>px;left:calc(<?php echo 100*$slot['lane']/$slot['lanes']; ?>% + 4px);width:calc(<?php echo 100/$slot['lanes']; ?>% - 8px)" aria-haspopup="dialog"><strong><?php echo $time; ?></strong><span class="calendar-event-type"><?php echo app_escape(implode(' · ',$titles)); ?></span><small><?php echo count($slot['groups']).(count($slot['groups'])===1?' grupo':' grupos'); ?> · <?php echo $usedTotal; ?>/<?php echo $capacityTotal; ?> plazas</small><span class="calendar-event-monitor"><?php echo $names?app_escape(implode(', ',$names)):'Monitor pendiente'; ?></span></button>
 <?php } ?></section><?php } ?></div></div>
